{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; its absence cannot be inferred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted as repeat-run precision for an AI system. Relevant precision evidence is insufficient, corresponding to 0 rather than demonstrated inadequacy. Human temporal change is not assessed."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "Without repetitions, stability remains unknown; instability is not demonstrated."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, reinterpreted for AI repeat runs, no repeat-run precision estimate is available. This supports insufficient-information rating 0 for that evidence, not an inference that scores are unstable."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers examined repeated scores under matching conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates this alternative precision evidence, with 9.3 providing a repeat-testing analogy. The findings support the stated local stability criterion; they do not establish precision across other systems or conditions. Human sample-size and correlation anchors are not directly transferred to ten AI runs."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under matching conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "This range exceeds the report's maximum of two percentage points for stability."
        }
      ],
      "instrument_review": "EFPA 9.7 distinguishes conducting a precision study from obtaining acceptable precision. Reinterpreted for AI runs, these findings demonstrate inadequate stability under the report's stated criterion. Human correlation thresholds are not applied to the reported range."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions supply no evidence of repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions do not establish score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 addresses software instructions, while 9.3 and 9.7 address precision. Installation guidance concerns documentation and cannot substitute for repeat-run evidence. Human test-taker support questions are reinterpreted as support for benchmark operators."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher observed score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The results provide no evidence establishing superiority across domains."
        }
      ],
      "instrument_review": "EFPA 10.1 and 10.5 require evidence appropriate to the score interpretation. Reinterpreting test takers as AI systems, the observed comparison fits the narrow intended use; general intelligence requires additional validity evidence. Human population norms are not needed for this raw-score comparison under 8.3.2.2."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The observed grid-puzzle score is higher for A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Declaring a broad intended use does not establish the required cross-domain evidence."
        }
      ],
      "instrument_review": "EFPA 10.1 and 10.5 assess validity for the intended interpretation. With AI systems replacing human test takers, the narrow result remains supported, but the stated general-intelligence selection purpose lacks sufficient validity evidence. Missing evidence does not demonstrate that A lacks greater general intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence connects those scores to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A; its reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness results alone do not establish an improvement in workplace safety."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 and 10.3.2 accommodate experimental and external-criterion evidence. Here, correctness is the measured criterion for AI assistance, and inspectors are trial participants rather than benchmark test takers. Random allocation, blinded checking, and reported uncertainty support the workshop-specific use; other workshops, time, and safety remain unestablished."
    }
  ],
  "closing_note": "No unresolved instruction ambiguity. The requested probe format permits relevant-section reviews rather than complete forms. Labels classify statements, not EFPA ratings; no aggregate quality score was calculated. Human-specific questions were reinterpreted explicitly where relevant, without assuming applicability elsewhere."
}
